import { getUpdateVersionKey, Log, useWatchUpdates } from "@fanfanlo"
import { useContext } from "react"
import { Action } from "./action/Action"
import { ActionGroupContext } from "@droid/project-v2-interface"
import _ from "lodash"

const fileLog = new Log(true, 'ActionList');
fileLog.pause = true;

export function ActionList(){
    const actionGroup = useContext(ActionGroupContext)
    // 修改：监听children而不是list（web端主要使用children）
    const [children] = useWatchUpdates(actionGroup.children)
    if(!children || !_.isArray(children)){
        fileLog.log('children is null or not array', actionGroup)
    }
    fileLog.log('actionGroup=', JSON.stringify(actionGroup));

    // 使用 children 获取完整对象，而不是 list
    const childrenArray = actionGroup.children || [];
    fileLog.log('children.length=', childrenArray.length);

    return <div>
        {childrenArray.map((action, index) => {
            fileLog.log(`render action index=${index}, action=`, action);
            if (!action) {
                fileLog.error(`action is undefined at index=${index}`);
                return null;
            }
            return <Action key={getUpdateVersionKey(action)} actionData={action} actionGroup={actionGroup} index={index} />
        })}
    </div>
}
