import { Log, useTranslation, TFunction } from '@fanfanlo';
import { Box, CircularProgress, Typography, Button } from '@mui/material';
import { useRouter } from 'next/router';
import { useEffect, useState } from 'react';
import { ulid as generateUlid } from 'ulid';
import { getProjectR2Url } from '@app/model';
import { projectStore, IProject } from '@droid/project-v2-interface';

const fileLog = new Log(false, 'MarketModeWrapper_f');
// fileLog.pause = true;
// fileLog.childrenPaused = true;

export enum MarketModeLoadingState {
    Idle = 'idle',
    LoadingUrl = 'loadingUrl',
    LoadingData = 'loadingData',
    Success = 'success',
    Error = 'error'
}

export interface IMarketModeWrapperProps {
    children: React.ReactNode;
}

/**
 * 重新生成 project 及所有子孙级的 ulid
 * 用于从市场加载项目时，创建独立的本地副本
 */
function regenerateAllUlids(project: IProject, log: Log): void {
    const fnLog = log.sub(false, 'regenerateAllUlids_fn');

    const oldProjectUlid = project.ulid;
    project.ulid = generateUlid();
    fnLog.log('[regenerateAllUlids] project.ulid:', oldProjectUlid, '->', project.ulid);

    if (!project.children) {
        fnLog.log('[regenerateAllUlids] project.children 为空，跳过');
        return;
    }

    for (let i = 0; i < project.children.length; i++) {
        const triggerActionGroup = project.children[i];
        const oldTagUlid = triggerActionGroup.ulid;
        triggerActionGroup.ulid = generateUlid();
        fnLog.log('[regenerateAllUlids] triggerActionGroup[' + i + '].ulid:', oldTagUlid, '->', triggerActionGroup.ulid);

        if (!triggerActionGroup.children) {
            fnLog.log('[regenerateAllUlids] triggerActionGroup[' + i + '].children 为空，跳过');
            continue;
        }

        for (let j = 0; j < triggerActionGroup.children.length; j++) {
            const triggerAction = triggerActionGroup.children[j];
            const oldTaUlid = triggerAction.ulid;
            triggerAction.ulid = generateUlid();
            fnLog.log('[regenerateAllUlids] triggerAction[' + i + '][' + j + '].ulid:', oldTaUlid, '->', triggerAction.ulid);

            // 处理 triggerGroup
            if (triggerAction.triggerGroup) {
                const oldTgUlid = triggerAction.triggerGroup.ulid;
                triggerAction.triggerGroup.ulid = generateUlid();
                triggerAction.triggerGroupUlid = triggerAction.triggerGroup.ulid;
                fnLog.log('[regenerateAllUlids] triggerGroup[' + i + '][' + j + '].ulid:', oldTgUlid, '->', triggerAction.triggerGroup.ulid);

                if (triggerAction.triggerGroup.children) {
                    for (let k = 0; k < triggerAction.triggerGroup.children.length; k++) {
                        const trigger = triggerAction.triggerGroup.children[k];
                        const oldTriggerUlid = trigger.ulid;
                        trigger.ulid = generateUlid();
                        fnLog.log('[regenerateAllUlids] trigger[' + i + '][' + j + '][' + k + '].ulid:', oldTriggerUlid, '->', trigger.ulid);
                    }
                }
            }

            // 处理 actionGroup
            if (triggerAction.actionGroup) {
                const oldAgUlid = triggerAction.actionGroup.ulid;
                triggerAction.actionGroup.ulid = generateUlid();
                triggerAction.actionGroupUlid = triggerAction.actionGroup.ulid;
                fnLog.log('[regenerateAllUlids] actionGroup[' + i + '][' + j + '].ulid:', oldAgUlid, '->', triggerAction.actionGroup.ulid);

                if (triggerAction.actionGroup.children) {
                    for (let k = 0; k < triggerAction.actionGroup.children.length; k++) {
                        const action = triggerAction.actionGroup.children[k];
                        const oldActionUlid = action.ulid;
                        action.ulid = generateUlid();
                        fnLog.log('[regenerateAllUlids] action[' + i + '][' + j + '][' + k + '].ulid:', oldActionUlid, '->', action.ulid);
                    }
                }
            }
        }
    }

    fnLog.log('[regenerateAllUlids] 完成');
}

export function MarketModeWrapper({ children }: IMarketModeWrapperProps) {
    const uiLog = fileLog.sub(false, 'MarketModeWrapper_ui');

    const router = useRouter();
    const { t } = useTranslation('droid-project-v2-ui/ui/project/edit-project/content');

    const [loadingState, setLoadingState] = useState<MarketModeLoadingState>(MarketModeLoadingState.Idle);
    const [errorMsg, setErrorMsg] = useState<string>('');

    const mode = router.query.mode as string | undefined;
    const uuid = router.query.uuid as string | undefined;
    const urlUlid = router.query.ulid as string | undefined;
    const isMarketMode = mode === 'market';

    uiLog.log('[MarketModeWrapper] mode:', mode, 'uuid:', uuid, 'urlUlid:', urlUlid, 'isMarketMode:', isMarketMode);

    useEffect(() => {
        const fnLog = uiLog.sub(false, 'effect_loadMarketProject_fn');

        fnLog.log('[loadMarketProject] isMarketMode:', isMarketMode, 'uuid:', uuid, 'urlUlid:', urlUlid);

        if (!isMarketMode) {
            return;
        }

        if (!uuid) {
            setLoadingState(MarketModeLoadingState.Error);
            setErrorMsg(t('MarketModeWrapper.error.missingUuid'));
            return;
        }

        // 如果 URL 已有 ulid，说明已经加载过，检查本地是否存在
        if (urlUlid) {
            const existingByUlid = projectStore.findDraftOrSavedProject(urlUlid);
            fnLog.log('[loadMarketProject] URL 有 ulid, 检查本地, existingByUlid:', existingByUlid ? existingByUlid.ulid : 'null');
            if (existingByUlid) {
                setLoadingState(MarketModeLoadingState.Success);
                return;
            }
        }

        loadMarketProject(uuid, fnLog, t, router);
    }, [isMarketMode, uuid, urlUlid, t]);

    async function loadMarketProject(uuid: string, log: Log, t: TFunction, router: ReturnType<typeof useRouter>) {
        setLoadingState(MarketModeLoadingState.LoadingUrl);
        setErrorMsg('');

        // 1. 获取 R2 URL
        const r2UrlResult = await getProjectR2Url({
            params: {
                data: { uuid }
            }
        });

        log.log('[loadMarketProject] getProjectR2Url 结果, shellIsOk:', r2UrlResult.shellIsOk, 'dataIsOk:', r2UrlResult.dataIsOk, 'is_ok:', r2UrlResult.data?.is_ok, 'url:', r2UrlResult.data?.url);

        if (!r2UrlResult.shellIsOk || !r2UrlResult.data) {
            setLoadingState(MarketModeLoadingState.Error);
            setErrorMsg(t('MarketModeWrapper.error.fetchUrlFailed'));
            return;
        }

        if (!r2UrlResult.data.is_ok) {
            setLoadingState(MarketModeLoadingState.Error);
            const msg = r2UrlResult.data.msg;
            if (msg) {
                setErrorMsg(msg);
            } else {
                setErrorMsg(t('MarketModeWrapper.error.projectNotExist'));
            }
            return;
        }

        const r2Url = r2UrlResult.data.url;
        if (!r2Url) {
            setLoadingState(MarketModeLoadingState.Error);
            setErrorMsg(t('MarketModeWrapper.error.urlEmpty'));
            return;
        }

        // 2. Fetch 项目数据
        setLoadingState(MarketModeLoadingState.LoadingData);

        try {
            const response = await fetch(r2Url);
            log.log('[loadMarketProject] fetch 响应, ok:', response.ok, 'status:', response.status);

            if (!response.ok) {
                setLoadingState(MarketModeLoadingState.Error);
                setErrorMsg(t('MarketModeWrapper.error.fetchDataFailed'));
                return;
            }

            const projectData = await response.json() as IProject;
            log.log('[loadMarketProject] 获取到项目数据, title:', projectData.title, 'uuid:', projectData.uuid);

            // 3. 重新生成所有 ulid（创建独立的本地副本）
            regenerateAllUlids(projectData, log);

            // 4. 存入 draft
            projectStore.addDraft(projectData);
            log.log('[loadMarketProject] 已存入 draft, ulid:', projectData.ulid);

            // 5. 更新 URL 添加 ulid 参数，让 EditProjectBuilder 能找到项目
            const currentQuery = { ...router.query };
            currentQuery.ulid = projectData.ulid;
            log.log('[loadMarketProject] 更新 URL, 添加 ulid:', projectData.ulid);
            router.replace(
                {
                    pathname: router.pathname,
                    query: currentQuery
                },
                undefined,
                { shallow: true }
            );

            setLoadingState(MarketModeLoadingState.Success);

        } catch (error) {
            log.log('[loadMarketProject] ERROR: fetch 异常:', error);
            setLoadingState(MarketModeLoadingState.Error);
            setErrorMsg(t('MarketModeWrapper.error.fetchDataFailed'));
        }
    }

    function handleRetry() {
        const fnLog = uiLog.sub(false, 'handleRetry_fn');
        fnLog.log('[handleRetry] 重试加载, uuid:', uuid);
        if (uuid) {
            loadMarketProject(uuid, fnLog, t, router);
        }
    }

    function handleBack() {
        const fnLog = uiLog.sub(false, 'handleBack_fn');
        fnLog.log('[handleBack] 返回市场页面');
        router.push('/fanfanlo/market');
    }

    // 非市场模式，直接渲染子组件
    if (!isMarketMode) {
        return <>{children}</>;
    }

    // 加载中状态
    const isLoadingState = loadingState === MarketModeLoadingState.Idle ||
        loadingState === MarketModeLoadingState.LoadingUrl ||
        loadingState === MarketModeLoadingState.LoadingData;

    if (isLoadingState) {
        return (
            <MarketModeLoadingUI
                loadingState={loadingState}
            />
        );
    }

    // 错误状态
    if (loadingState === MarketModeLoadingState.Error) {
        return (
            <MarketModeErrorUI
                errorMsg={errorMsg}
                onBack={handleBack}
                onRetry={handleRetry}
            />
        );
    }

    // 加载成功，渲染子组件
    return <>{children}</>;
}

// ============ 状态组件 ============

interface IMarketModeLoadingUIProps {
    loadingState: MarketModeLoadingState;
}

function MarketModeLoadingUI({ loadingState }: IMarketModeLoadingUIProps) {
    const uiLog = fileLog.sub(false, 'MarketModeLoadingUI_ui');
    const { t } = useTranslation('droid-project-v2-ui/ui/project/edit-project/content');

    let loadingText = t('MarketModeWrapper.loading.default');
    if (loadingState === MarketModeLoadingState.LoadingUrl) {
        loadingText = t('MarketModeWrapper.loading.url');
    } else if (loadingState === MarketModeLoadingState.LoadingData) {
        loadingText = t('MarketModeWrapper.loading.data');
    }

    uiLog.log('[MarketModeLoadingUI] loadingState:', loadingState, 'loadingText:', loadingText);

    return (
        <Box
            sx={{
                display: 'flex',
                flexDirection: 'column',
                justifyContent: 'center',
                alignItems: 'center',
                height: '100%',
                gap: 2
            }}
            data-testid="MarketModeWrapper__loading__01jw9a1b2c3d4e5f6g7h8i9j"
            data-test-comment="市场模式加载中状态"
        >
            <CircularProgress />
            <Typography color="text.secondary">
                {loadingText}
            </Typography>
        </Box>
    );
}

interface IMarketModeErrorUIProps {
    errorMsg: string;
    onBack: () => void;
    onRetry: () => void;
}

function MarketModeErrorUI({ errorMsg, onBack, onRetry }: IMarketModeErrorUIProps) {
    const uiLog = fileLog.sub(false, 'MarketModeErrorUI_ui');
    const { t } = useTranslation('droid-project-v2-ui/ui/project/edit-project/content');

    uiLog.log('[MarketModeErrorUI] errorMsg:', errorMsg);

    return (
        <Box
            sx={{
                display: 'flex',
                flexDirection: 'column',
                justifyContent: 'center',
                alignItems: 'center',
                height: '100%',
                gap: 2
            }}
            data-testid="MarketModeWrapper__error__01jw9a1b2c3d4e5f6g7h8i9k"
            data-test-comment="市场模式错误状态"
        >
            <Typography color="error">
                {errorMsg}
            </Typography>
            <Box sx={{ display: 'flex', gap: 2 }}>
                <Button
                    variant="outlined"
                    onClick={onBack}
                    data-testid="MarketModeWrapper__backButton__01jw9a1b2c3d4e5f6g7h8i9l"
                    data-test-comment="返回市场页面按钮"
                >
                    {t('MarketModeWrapper.error.back')}
                </Button>
                <Button
                    variant="contained"
                    onClick={onRetry}
                    data-testid="MarketModeWrapper__retryButton__01jw9a1b2c3d4e5f6g7h8i9m"
                    data-test-comment="重试按钮"
                >
                    {t('MarketModeWrapper.error.retry')}
                </Button>
            </Box>
        </Box>
    );
}
